const $=s=>document.querySelector(s);
const models={pro:{name:'Azure One Pro',base:69999,finishes:['Cosmic Violet','Graphite','Natural Sand'],storage:['256 GB','512 GB']},one:{name:'Azure One',base:44999,finishes:['Natural Sand','Sage','Graphite'],storage:['128 GB','256 GB']}};
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
let bag=[];try{const saved=JSON.parse(localStorage.getItem('azure-preview-bag')||'[]');if(Array.isArray(saved))bag=saved.filter(i=>models[i.model]&&models[i.model].finishes.includes(i.finish)&&models[i.model].storage.includes(i.storage)).slice(0,20).map(i=>({...i,price:models[i.model].base+(models[i.model].storage.indexOf(i.storage)?10000:0)}));}catch{}
let current='pro',toastTimer;
const persist=()=>{try{localStorage.setItem('azure-preview-bag',JSON.stringify(bag));}catch{}$('#bag-count').textContent=bag.length;};
const toast=message=>{$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);};
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
$('.menu-button').addEventListener('click',()=>{const opened=$('nav').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',opened);$('.menu-button').setAttribute('aria-label',opened?'Close menu':'Open menu');});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Open menu');}));
const finishes={blue:['#a8bcd0','#e1eaf0','Cosmic Violet'],black:['#626a71','#aeb8c0','Graphite'],sand:['#c7bca8','#e7e0d3','Natural Sand']};
document.querySelectorAll('.swatch').forEach(button=>button.addEventListener('click',()=>{const [tone,light,name]=finishes[button.dataset.color];document.documentElement.style.setProperty('--phone',tone);document.documentElement.style.setProperty('--phone-light',light);$('#finish-name').textContent=name;document.querySelectorAll('.swatch').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});}));
const art=$('.hero-art'),stage=$('#phone-stage');if(matchMedia('(pointer:fine) and (min-width:1001px) and (prefers-reduced-motion:no-preference)').matches){art.addEventListener('pointermove',e=>{const r=art.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;stage.style.transform=`rotateY(${x*12}deg) rotateX(${-y*8}deg) translateY(${-y*5}px)`;});art.addEventListener('pointerleave',()=>stage.style.transform='');}
function updatePrice(){$('#config-price').textContent=money(models[current].base+($('#storage').selectedIndex?10000:0));}
document.querySelectorAll('.configure').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.model;const model=models[current];$('#product-title').textContent=model.name;$('#finish').replaceChildren(...model.finishes.map(value=>new Option(value,value)));$('#storage').replaceChildren(...model.storage.map(value=>new Option(value,value)));updatePrice();$('#product-dialog').showModal();}));
$('#storage').addEventListener('change',updatePrice);
$('#configuration-form').addEventListener('submit',e=>{e.preventDefault();if(bag.length>=20){toast('Your preview bag is full. Remove an item to add another.');return;}bag.push({model:current,finish:$('#finish').value,storage:$('#storage').value,price:models[current].base+($('#storage').selectedIndex?10000:0)});persist();$('#product-dialog').close();toast(`${models[current].name} added to your preview bag`);});
function renderBag(){const items=$('#bag-items');items.replaceChildren();if(!bag.length){const p=document.createElement('p');p.className='empty-bag';p.textContent='A little possibility awaits. Explore the collection and add your favorite Azure.';items.append(p);const b=document.createElement('button');b.className='button primary';b.textContent='Explore phones ↗';b.onclick=()=>{$('#bag-dialog').close();$('#collection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});};items.append(b);$('#bag-summary').replaceChildren();return;}bag.forEach((item,index)=>{const row=document.createElement('div');row.className='bag-item';const info=document.createElement('div');const h=document.createElement('h3');h.textContent=models[item.model].name;const p=document.createElement('p');p.textContent=`${item.finish} · ${item.storage}`;const strong=document.createElement('strong');strong.textContent=money(item.price);info.append(h,p,strong);const remove=document.createElement('button');remove.className='remove-item';remove.textContent='Remove';remove.setAttribute('aria-label',`Remove ${models[item.model].name} in ${item.finish}`);remove.onclick=()=>{bag.splice(index,1);persist();renderBag();};row.append(info,remove);items.append(row);});$('#bag-summary').innerHTML=`<div class="bag-total"><span>Preview total</span><strong>${money(bag.reduce((s,i)=>s+i.price,0))}</strong></div><p class="concept-note">This is your concept selection, not an order. Checkout, payment, taxes and delivery will be connected after the design is approved.</p>`;}
$('.bag-button').addEventListener('click',()=>{renderBag();$('#bag-dialog').showModal();});
$('#film-button').addEventListener('click',()=>$('#story-dialog').showModal());$('#story-link').addEventListener('click',()=>$('#story-dialog').close());$('#privacy-button').addEventListener('click',()=>$('#privacy-dialog').showModal());$('#year').textContent=new Date().getFullYear();persist();

const scenes=[['01 / After the last light',''],['02 / The blue hour','blue-hour'],['03 / A warmer perspective','warm-hour']];let scene=0;
function renderScene(){const [caption,tone]=scenes[scene];$('.landscape').className='landscape '+tone;$('#gallery-caption').textContent=caption;}
$('#gallery-next').onclick=()=>{scene=(scene+1)%scenes.length;renderScene();};$('#gallery-prev').onclick=()=>{scene=(scene+scenes.length-1)%scenes.length;renderScene();};
document.querySelectorAll('[data-lens]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-lens]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('.landscape').style.setProperty('--zoom',b.dataset.lens==='3'?'1.5':b.dataset.lens==='1'?'1.15':'1');});
const sections=document.querySelectorAll('main section[id]');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('current',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});});},{rootMargin:'-15% 0px -60% 0px'});sections.forEach(s=>observer.observe(s));
